parameters.jsCode:
const tickets = $input.all();

// Solo tickets activos
const activos = tickets
  .map(item => item.json)
  .filter(ticket =>
    ['NUEVO', 'ASIGNADO', 'EN_PROCESO'].includes(ticket.fields?.estado)
  );

// Ordenar por fecha de creación, del más reciente al más antiguo
activos.sort((a, b) => {
  const fechaA = new Date(a.fields?.fecha_creacion || 0);
  const fechaB = new Date(b.fields?.fecha_creacion || 0);
  return fechaB - fechaA;
});

// Chat del usuario
const chat_id = activos[0]?.fields?.chat_id || tickets[0]?.json?.fields?.chat_id || '';

let texto;

if (activos.length === 0) {
  texto =
    '🎫 <b>Mis tickets</b>\n\n' +
    'No tenés tickets activos en este momento.';
} else {
  texto =
    '🎫 <b>Mis tickets activos</b>\n\n' +
    `Tenés <b>${activos.length}</b> ticket(s) en seguimiento:\n\n`;

  activos.forEach((ticket, index) => {
    const f = ticket.fields;

    texto +=
      `<b>${index + 1}. ${f.ticket_id}</b>\n` +
      `📌 Estado: <b>${f.estado}</b>\n` +
      `📂 Categoría: ${f.categoria}\n` +
      `⚠️ Prioridad: <b>${f.prioridad}</b>\n` +
      `👥 Equipo: ${f.equipo_responsable}\n\n`;
  });
}

return [
  {
    json: {
      chat_id,
      cantidad_tickets: activos.length,
      texto
    }
  }
];

